"""Interaction and layout test for Dairy card 2. Usage: GFX_OUT=/path/to/repo GFX_SHOTS=/tmp/shots python3 test_card2.py"""
import os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from testlib import *
from playwright.sync_api import sync_playwright
repo = os.environ.get('GFX_OUT', 'out'); out = os.environ.get('GFX_SHOTS', 'shots')
ctx = Ctx(repo, 8811, out); N = 2
def num(s): return float(re.sub(r'[^0-9.]', '', s))
with sync_playwright() as p:
    layout_rules(ctx, p, N, lambda h: (h.click('#runs [data-r="BT"]')))
    b, pg, errs, h = ctx.open(p, N)
    ctx.chk('start: stage hidden, empty prompt shown', 'off' in h.cls('#fwb').split() and 'Choose a production run' in h.txt('.emp'))
    ctx.chk('start: no counts, totals or percentages on screen', not re.search(r'\d,\d{3}|\d+\.\d%|\d+%|\$\d', h.vis_text()), h.vis_text()[:200])
    h.click('#runs [data-r="BT"]'); pg.wait_for_timeout(1000)
    t = lambda i: h.txt('#' + i)
    ctx.chk('butter: yield numbers', (t('vexp'), t('vact'), t('sIn'), t('sStd'), t('sAct'), t('sVar')) == ('2,300 lb', '2,240 lb', '4,800 lb', '47.9%', '46.7%', '60 lb under, 2.6%'), str([t(i) for i in ('vexp', 'vact', 'sIn', 'sStd', 'sAct', 'sVar')]))
    ctx.chk('butter 6%: cost rows', [t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')] == ['94%', '$7,760.64', '$3.46', '6%', '$495.36', '$0.20'], str([t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')]))
    ol = [num(x) for x in re.findall(r'([\d,]+) lb', h.txt('#ol'))]; ctx.chk('butter outputs add up to the 4,800 lb input', sum(ol) == 4800, str(ol))
    ctx.chk('butter input cost shown', t('icost')=='$8,256.00' and 'Input cost, 4,800 lb at $1.72' in t('icl'), t('icl')+t('icost'))
    ctx.chk('butter costs add up', abs(num(t('k1')) + num(t('k2')) - 4800 * 1.72) < 0.01)
    h.click('#shr [data-i="2"]'); pg.wait_for_timeout(500)
    ctx.chk('butter 8%: cost rows', [t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')] == ['92%', '$7,595.52', '$3.39', '8%', '$660.48', '$0.26'], str([t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')]))
    h.click('#shr [data-i="0"]'); pg.wait_for_timeout(500)
    ctx.chk('butter 4%: cost rows', [t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')] == ['96%', '$7,925.76', '$3.54', '4%', '$330.24', '$0.13'], str([t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')]))
    h.click('#cvb'); pg.wait_for_timeout(500)
    ctx.chk('butter convert: 7 totes to 56 cases', '2,240 one pound prints, 56 cases' in t('cvR') and t('cvb') == 'Converted' and h.dis('#cvb') and '7 totes' in t('cvL') and 'PR-1031-1' in t('cvR'), t('cvR'))
    ctx.chk('prints and cases agree (2,240 prints, 40 per case)', 2240 / 40 == 56 and 2240 / 7 == 320); h.shot(out, 'c2-butter-converted')
    h.click('#runs [data-r="CH"]'); pg.wait_for_timeout(1000)
    ctx.chk('cheddar: yield numbers', (t('vexp'), t('vact'), t('sIn'), t('sStd'), t('sAct'), t('sVar')) == ('2,000 lb', '1,960 lb', '20,000 lb', '10.0%', '9.8%', '40 lb under, 2.0%'), str([t(i) for i in ('vexp', 'vact', 'sIn', 'sStd', 'sAct', 'sVar')]))
    ctx.chk('cheddar 8%: cost rows', [t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')] == ['92%', '$4,048.00', '$2.07', '8%', '$352.00', '$0.02'], str([t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')]))
    ol = [num(x) for x in re.findall(r'([\d,]+) lb', h.txt('#ol'))]; ctx.chk('cheddar outputs add up to 20,000 lb', sum(ol) == 20000, str(ol))
    ctx.chk('cheddar input cost shown', t('icost')=='$4,400.00' and 'at $0.22' in t('icl'), t('icl')+t('icost'))
    ctx.chk('cheddar conversion reads 49 blocks to 196 cases', 49 * 40 == 1960 and 1960 * 2 == 3920 and 3920 / 20 == 196)
    h.click('#shr [data-i="0"]'); pg.wait_for_timeout(400); ctx.chk('cheddar 6%: cost rows', [t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')] == ['94%', '$4,136.00', '$2.11', '6%', '$264.00', '$0.01'])
    h.click('#shr [data-i="2"]'); pg.wait_for_timeout(400); ctx.chk('cheddar 10%: cost rows', [t(i) for i in ('s1', 'k1', 'p1', 's2', 'k2', 'p2')] == ['90%', '$3,960.00', '$2.02', '10%', '$440.00', '$0.02'])
    h.click('.rp'); pg.wait_for_timeout(1500); ctx.chk('replay returns to the empty start', 'off' in h.cls('#fwb').split() and t('vchip') == 'No run selected')
    b.close()
    speed(ctx, p, N, "return /under standard/.test(r.getElementById('vchip').textContent)")
    arrows_generic(ctx, p, N, 5)
    # steps: states
    b, pg, errs, h = ctx.open(p, N)
    h.click('#nx'); pg.wait_for_timeout(900); ctx.chk('step 1 opens butter', h.txt('#sn') == '2 of 5' and t('vexp') == '2,300 lb')
    h.click('#nx'); pg.wait_for_timeout(700); ctx.chk('step 3 sets 8%', t('s2') == '8%' and t('p1') == '$3.39', t('p1'))
    ctx.chk('step 3 hotspot on the convert button', h.ev("const x=r.querySelector('#hs').getBoundingClientRect(),y=r.querySelector('#cvb').getBoundingClientRect();return Math.abs(x.left-y.left)<8&&Math.abs(x.top-y.top)<8"))
    h.click('#nx'); pg.wait_for_timeout(700); ctx.chk('step 4 converts', t('cvb') == 'Converted')
    h.click('#nx'); pg.wait_for_timeout(900); ctx.chk('step 5 shows cheddar', 'Cheddar' in t('ychip') and t('vexp') == '2,000 lb')
    h.shot(out, 'c2-step5'); b.close()
    # tour in order (butter opens 2.4 s, 8% at 9.0 s, converts 13.4 s, cheddar 17.8 s after mount)
    b, pg, errs, h = ctx.open(p, N); pg.wait_for_timeout(2600); h.shot(out, 'c2-tour-1'); ctx.chk('tour: butter open by 2.6 s', t('vexp') == '2,300 lb')
    pg.wait_for_timeout(7400); h.shot(out, 'c2-tour-2'); ctx.chk('tour: 8% cost share set', t('s2') == '8%', t('s2'))
    pg.wait_for_timeout(4200); h.shot(out, 'c2-tour-3'); ctx.chk('tour: converted', t('cvb') == 'Converted', t('cvb'))
    pg.wait_for_timeout(4400); h.shot(out, 'c2-tour-4'); ctx.chk('tour: cheddar', 'Cheddar' in t('ychip'), t('ychip')); b.close()
ctx.close(); print('RESULT:', 'PASS' if not ctx.fails else 'FAIL ' + str(ctx.fails))
